    best=min([cc for cc in cs if len(cc[1])>max(len(q[1]) for q in cs if True)],key=lambda cc:(cnt[cc[0]],-len(cc[1])))
    cells={p for p in best[1]}
    H,W=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    for dr in range(-H,H):
        for dc in range(-W,W):
            if all(0<=p[0]+dr<H and 0<=p[1]+dc<W and grid[p[0]+dr][p[1]+dc]!=bg for p in cells):
                for p in cells: out[p[0]+dr][p[1]+dc]=grid[p[0]][p[1]]
    return out
