def comps8(grid,bg):
    H,W=len(grid),len(grid[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if grid[r][c]!=bg and not seen[r][c]:
                col=grid[r][c]; q=deque([(r,c)]); seen[r][c]=True; cells=set()
                while q:
                    y,x=q.popleft(); cells.add((y,x))
                    for dy in (-1,0,1):
                        for dx in (-1,0,1):
                            if dy==dx==0: continue
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and grid[ny][nx]==col:
                                seen[ny][nx]=True; q.append((ny,nx))
                out.append((col,cells))
    return out
